// Additional authored choices for the three-pick coverage target. Every row
// names the opponent, native roles, threat, timing and failure condition.
// Shared mechanics are reused only for these explicitly reviewed pairings.
function addCounterOption(candidate, enemy, reviewedRoles, answerSlot, threatSlot, plan, why, play, risk, runeWhy, options = {}) {
  const missingRoles = reviewedRoles.filter(role => !counterMatchupRules.some(rule =>
    rule.candidate === candidate && rule.enemy === enemy && rule.role === role && rule.enemyRole === role));
  addReviewedRoleMatchups(candidate, enemy, missingRoles, answerSlot, threatSlot, plan, why, play, risk, runeWhy, { priority: 3, ...options });
}

